'use client'
// AO-2063 — DO NOT EDIT THIS FILE.
//
// It is a byte-for-byte copy of connector/PlatformTopBarConnector.tsx in
// @comet/ui (AltaVue/altavue-ui), identical in all eight AltaVue apps. The
// build checks it (comet-ui-verify, run from next.config.ts) and the Drift
// Guard checks it again; any difference fails the build. To change the top bar,
// change @comet/ui, tag a new version and move every app up together.
//
// What it does: reads the signed-in person, their module access, the reports
// list and search through this app's own Supabase client (@altavue/auth), and
// hands them to the shared, display-only bar. The module comes from
// lib/platformModule.ts.
import { useCallback, useEffect, useState } from 'react'
import { usePathname } from 'next/navigation'
import { createClient } from '@altavue/auth/client'
import { getModuleAccess } from '@altavue/auth/entitlement'
import {
  PlatformTopBar,
  resolveModuleForPath,
  type ModuleAccessLike,
  type ReportRow,
  type SearchResultRow,
  type TopBarUser,
} from '@comet/ui/topbar'
import { PLATFORM_MODULE } from '@/lib/platformModule'

export default function PlatformTopBarConnector() {
  const pathname = usePathname()
  const [user, setUser] = useState<TopBarUser | null | undefined>(undefined)
  const [access, setAccess] = useState<ModuleAccessLike | null | undefined>(undefined)
  const [reports, setReports] = useState<ReportRow[] | null | undefined>(undefined)

  useEffect(() => {
    let live = true
    const supabase = createClient()

    supabase.auth
      .getUser()
      .then(async ({ data }) => {
        const u = data.user
        if (!live) return
        if (!u) {
          setUser(null)
          return
        }
        const { data: profile } = await supabase
          .from('profiles')
          .select('full_name, avatar_url')
          .eq('id', u.id)
          .maybeSingle()
        if (!live) return
        const base = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/$/, '')
        const avatarUrls = [
          profile?.avatar_url ?? null,
          base ? `${base}/storage/v1/object/public/avatars/${u.id}/avatar.jpg` : null,
        ].filter((x): x is string => typeof x === 'string' && x.length > 0)
        setUser({ email: u.email ?? null, fullName: profile?.full_name ?? null, avatarUrls })
      })
      .catch(() => {
        if (live) setUser(null)
      })

    getModuleAccess(supabase)
      .then((a) => {
        if (live) setAccess(a)
      })
      .catch(() => {
        if (live) setAccess(null)
      })

    supabase
      .from('report_registry')
      .select('id, slug, title, description, category, route, icon, sort_order')
      .order('category', { ascending: true })
      .order('sort_order', { ascending: true })
      .then(({ data, error }) => {
        if (live) setReports(error ? null : ((data ?? []) as ReportRow[]))
      })

    return () => {
      live = false
    }
  }, [])

  const search = useCallback(async (query: string): Promise<SearchResultRow[]> => {
    const { data, error } = await createClient().rpc('comet_search', { p_query: query, p_limit: 5 })
    if (error) throw new Error('search failed')
    return (data ?? []) as SearchResultRow[]
  }, [])

  const onSignOut = useCallback(async () => {
    try {
      await createClient().auth.signOut()
    } catch (err) {
      console.error('Sign out failed:', err)
    }
    window.location.assign('/login')
  }, [])

  return (
    <PlatformTopBar
      module={resolveModuleForPath(PLATFORM_MODULE, pathname)}
      user={user}
      moduleAccess={access}
      reports={reports}
      search={search}
      onSignOut={onSignOut}
    />
  )
}
